#include <stdio.h>
#include <stdlib.h>

int main() {
    // int 1개 크기(4바이트)만큼 힙에 요청
    int *p = (int*)malloc(sizeof(int));

    if (p == NULL) {
        printf("Memory full!\n");
        return 1;
    }

    *p = 100; // 빌린 공간 사용
    printf("Stored in heap: %d\n", *p);

    free(p); // 반납 필수
    return 0;
}
